Fetch Form Submissions.code:
// Get new submissions of the pregnancy registration form.
// Note: fetchSubmissions() is not used here: it reads state.data.response.results,
// which changesApi() never sets, and it does not resolve $ references in its postUrl.
changesApi(
  // 1) Changes feed params; the cursor from the last run is used automatically.
  { include_docs: true, 'last-event-id': 0 },
  // 2) Callback: keep only the 'pregnancy' form submissions.
  state => {
    const submissions = state.data.results
      .map(change => change.doc)
      .filter(doc => doc && doc.form === 'pregnancy')
      .map(({ _id, form, type, reported_date, contact, fields }) => ({
        _id,
        form,
        type,
        reported_date,
        contact,
        fields,
      }));
    return { ...state, data: { submissions } };
  }
);

Read Changes Feed.code:
// Read changes since the last run, with full documents.
changesApi({
  include_docs: true,
  // Used on the first run only; later runs use state.cursor.
  'last-event-id': 0,
});

Fetch Specific Documents.code:
// Read changes for specific documents only.
changesApi({
  include_docs: true,
  // Document ids to filter on.
  doc_ids: $.data.contactIds,
});

Get Reports for One Form.code:
// Read changes, then keep only reports for one form.
changesApi(
  { include_docs: true },
  // Callback: filter the results to 'delivery' reports.
  state => {
    const reports = state.data.results
      .map(change => change.doc)
      .filter(doc => doc && doc.form === 'delivery');
    return { ...state, data: { reports } };
  }
);
